        const { traits: optionTraits = [], lazy = false } = optionsOrFirstTrait as WorldOptions;
        if (!lazy) {
            world.init(...optionTraits);
        } else {
            lazyTraits = optionTraits;
        }
    } else {
        world.init(...(optionsOrFirstTrait ? [optionsOrFirstTrait, ...traits] : traits));
    }

    return world;
}

