export function checkQueryTrackingWithRelations(
    world: World,
    query: QueryInstance,
    entity: Entity,
    eventType: EventType,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    const first = checkQueryTracking(world, query, entity, eventType, eventGenerationId, eventBitflag);
